import * as v8 from "node:v8";
function main(): void {
  const V: any = v8;
  const hex = (b: any) => b.toString("hex");
  const roundTrip = (value: any) => {
    const s = new V.DefaultSerializer();
    s.writeHeader();
    s.writeValue(value);
    const buf = s.releaseBuffer();
    const d = new V.DefaultDeserializer(buf);
    d.readHeader();
    const out = d.readValue();
    return [hex(buf), typeof out === "bigint" ? out + "n" : out instanceof Date ? "D" + out.getTime() : out instanceof RegExp ? String(out) : out instanceof Map ? "Map" + JSON.stringify([...out]) : out instanceof Set ? "Set" + JSON.stringify([...out]) : JSON.stringify(out)];
  };
  console.log(roundTrip({ a: 1, b: "x", c: [1, 2, 3], d: null, e: true, f: 1.5, g: "Ā", h: -7 }));
  console.log(roundTrip([1, [2, [3]], { z: {} }]));
  console.log(roundTrip(new Map([[1, 2]])).join("|"), roundTrip(new Set([1, 2])).join("|"));
  console.log(roundTrip(new Date(0)).join("|"), roundTrip(/ab/gi).join("|"), roundTrip(10n).join("|"));
  const view = roundTrip(new Uint8Array([1, 2, 3]));
  console.log(view[0], view[1]);
  const o: any = {}; o.self = o;
  const s = new V.Serializer(); s.writeHeader(); s.writeValue(o); console.log(hex(s.releaseBuffer()));
  const raw = new V.Serializer(); raw.writeHeader(); raw.writeUint32(300); raw.writeUint64(1, 2); raw.writeDouble(1.5); raw.writeRawBytes(Buffer.from("ab"));
  const buf = raw.releaseBuffer(); console.log(hex(buf));
  const rd = new V.Deserializer(buf); console.log(rd.readHeader(), rd.getWireFormatVersion(), rd.readUint32(), rd.readUint64().join(), rd.readDouble(), rd.readRawBytes(2).toString());
  let msg = ""; try { new V.Serializer().writeValue(() => 1); } catch (e: any) { msg = e.message; } console.log(msg.endsWith(" could not be cloned."));
  console.log(Object.getPrototypeOf(V.DefaultSerializer) === V.Serializer, V.Serializer.length, V.Deserializer.length, typeof V.Serializer.prototype.writeValue);
  console.log(Object.keys(new V.GCProfiler()).length);
}
